import { PDFArray, PDFDict, PDFDocument, PDFName, PDFRawStream, decodePDFRawStream } from "pdf-lib";

/** Decode actual embedded-font text, including Cyrillic/Turkmen glyphs. This
 * exercises generated bytes without requiring a host PDF command in CI. */
export async function readDiagnosticPdfText(bytes: Uint8Array): Promise<string> {
  const pdf = await PDFDocument.load(bytes), result: string[] = [];
  for (const page of pdf.getPages()) {
    const resources = page.node.Resources();
    if (!resources) throw new Error("PDF has no resources");
    const fonts = resources.lookup(PDFName.of("Font"), PDFDict);
    const maps = new Map<string, Map<string, string>>();
    for (const [name, reference] of fonts.entries()) {
      const font = pdf.context.lookup(reference, PDFDict);
      const cmap = font.lookup(PDFName.of("ToUnicode"));
      if (!(cmap instanceof PDFRawStream)) throw new Error("PDF has no Unicode stream");
      const mapping = new Map<string, string>();
      const source = Buffer.from(decodePDFRawStream(cmap).decode()).toString("ascii");
      for (const block of source.matchAll(/beginbfchar([\s\S]*?)endbfchar/g)) {
        for (const pair of (block[1] ?? "").matchAll(/<([0-9a-f]+)>\s*<([0-9a-f]+)>/gi)) {
          if (!pair[1] || !pair[2]) throw new Error("Invalid PDF Unicode map");
          const codes = pair[2].match(/.{4}/g);
          if (!codes) throw new Error("Empty PDF Unicode mapping");
          mapping.set(pair[1].toUpperCase(), String.fromCharCode(...codes.map(code => parseInt(code, 16))));
        }
      }
      if (!mapping.size) throw new Error("PDF has no decoded font map");
      maps.set(name.toString(), mapping);
    }
    const contents = page.node.Contents();
    if (!contents) throw new Error("PDF has no content");
    const streams = contents instanceof PDFArray ? contents.asArray() : [contents];
    let currentFont = "";
    for (const reference of streams) {
      const stream = pdf.context.lookup(reference);
      if (!(stream instanceof PDFRawStream)) throw new Error("PDF has no content stream");
      const source = Buffer.from(decodePDFRawStream(stream).decode()).toString("ascii");
      for (const token of source.matchAll(/(\/[^\s]+)\s+[\d.]+\s+Tf|<([0-9a-f]+)>\s*Tj/gi)) {
        if (token[1]) currentFont = token[1];
        else {
          const codes = token[2]?.match(/.{4}/g);
          if (!codes) throw new Error("PDF has undecodable text");
          result.push(codes.map(code => {
            const value = maps.get(currentFont)?.get(code.toUpperCase());
            if (value === undefined) throw new Error("PDF contains an unmapped glyph");
            return value;
          }).join(""));
        }
      }
    }
  }
  if (!result.length) throw new Error("PDF has no decoded text");
  return result.join("\n");
}
